EVP_PKEY *RSAKey() {
  EVP_PKEY *pkey;
  RSA *rsa;
// 2048비트 이상으로 설정한 후에 사용해야 한다.
  rsa = RSA_generate_key(2048, 35, NULL, NULL);
  if(rsa == NULL) {
    printf("Error \n");
    return NULL;
  }
  pkey = EVP_PKEY_new();
  EVP_PKEY_assign_RSA(pkey, rsa);
  return pkey;
}
